syntax.code:
long fact(int n) {
  if (n <= 1) return 1;      /* base */
  return n * fact(n - 1);    /* recursive */
}

examples.code:
#include <stdio.h>
long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }
int sum_to(int n) { return n == 0 ? 0 : n + sum_to(n - 1); }
int main(void) { printf("%ld %d\n", fact(5), sum_to(5)); return 0; }

#include <stdio.h>
int fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }
int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
int main(void) { printf("%d %d\n", fib(10), gcd(48, 18)); return 0; }

