#include <stdio.h>
long fact(int n){return n<=1?1:n*fact(n-1);}
int sum(int n){return n==0?0:n+sum(n-1);}
int fib(int n){return n<2?n:fib(n-1)+fib(n-2);}
int main(void){printf("%ld %d %d\n",fact(5),sum(5),fib(10));return 0;}
